-- Full-text values: replace the short codes saved in records.data with their descriptions
-- ("W" -> "Widow", "VA" -> "Virginia", "A" -> "Application number"), for every list except the quality codes.
-- Also, in Country boxes (the ones a state fills in), "US"/"USA" become "United States" and ALL-CAPS words of 4+ letters
-- become normal case ("ENGLAND" -> "England"); short ones such as "UK" are left alone.
-- Generated from the code lists in js/schema.js at the time of the change. Safe to run again: only exact old codes
-- change, so values already in full text (and anything typed freely) are left alone.
-- Runs as postgres, so the new history versions it creates have no editor name (updated_by is null).

create or replace function pg_temp.fix_obj(o jsonb, fld text, m jsonb) returns jsonb language sql immutable as $$
  select case when jsonb_typeof(o) = 'object' and jsonb_typeof(o -> fld) = 'string' and m ? (o ->> fld)
              then jsonb_set(o, array[fld], m -> (o ->> fld)) else o end
$$;
create or replace function pg_temp.fix_obj_c(o jsonb, fld text) returns jsonb language sql immutable as $$
  select case when jsonb_typeof(o) = 'object' and jsonb_typeof(o -> fld) = 'string' then
           case when o ->> fld in ('US', 'USA') then jsonb_set(o, array[fld], to_jsonb('United States'::text))
                when o ->> fld ~ '^[A-Z][A-Z .''&-]{3,}$' then jsonb_set(o, array[fld], to_jsonb(initcap(lower(o ->> fld))))
                else o end
         else o end
$$;
create or replace function pg_temp.fix_arr_c(a jsonb, fld text) returns jsonb language sql immutable as $$
  select case when jsonb_typeof(a) = 'array'
              then coalesce((select jsonb_agg(pg_temp.fix_obj_c(e, fld) order by ord) from jsonb_array_elements(a) with ordinality as t(e, ord)), '[]'::jsonb)
              else a end
$$;
create or replace function pg_temp.fix_arr(a jsonb, fld text, m jsonb) returns jsonb language sql immutable as $$
  select case when jsonb_typeof(a) = 'array'
              then coalesce((select jsonb_agg(pg_temp.fix_obj(e, fld, m) order by ord) from jsonb_array_elements(a) with ordinality as t(e, ord)), '[]'::jsonb)
              else a end
$$;

